/* ---------- shared painters ---------- */
function seed(c,x,y,sz,g,crack){
  c.save();c.globalCompositeOperation='lighter';glow(c,x,y,sz*5,AMBER,.2*g);c.restore();
  // an almond-shaped seed: rounded at one end, pointed at the other, tilted with the point up and to the right
  const L=sz*1.25,w=sz*.5,tx=L*.58;c.save();c.translate(x,y);c.rotate(-.42);
  const body=()=>{c.beginPath();c.moveTo(tx,0);c.bezierCurveTo(tx*.35,-w*1.05,-L*.55,-w*1.0,-L*.48,0);c.bezierCurveTo(-L*.55,w*1.0,tx*.35,w*1.05,tx,0);c.closePath()};
  const gr=c.createRadialGradient(-L*.12,-w*.35,sz*.04,0,0,L*.7);
  gr.addColorStop(0,`rgba(255,200,130,${.5+.45*g})`);gr.addColorStop(.55,`rgba(186,98,36,${.6+.35*g})`);gr.addColorStop(1,'rgb(52,24,9)');
  body();c.fillStyle=gr;c.fill();
  // seed coat: a ridge down the length, faint grain lines, the pale scar near the point
  c.save();body();c.clip();c.lineCap='round';
  c.strokeStyle='rgba(60,25,8,.55)';c.lineWidth=Math.max(1,sz*.035);c.beginPath();c.moveTo(-L*.46,w*.04);c.quadraticCurveTo(0,w*.16,tx*.95,0);c.stroke();
  c.strokeStyle='rgba(255,210,150,.16)';c.lineWidth=Math.max(1,sz*.018);for(const k of[-.62,-.34,.36,.64]){c.beginPath();c.moveTo(-L*.42,w*k*.85);c.quadraticCurveTo(0,w*k*1.08,tx*.9,w*k*.2);c.stroke()}
  c.fillStyle='rgba(255,230,190,.12)';c.beginPath();c.ellipse(-L*.12,-w*.42,L*.28,w*.16,-.06,0,TAU);c.fill();
  c.restore();
  c.fillStyle='rgba(240,215,170,.75)';c.beginPath();c.ellipse(tx*.72,w*.06,sz*.07,sz*.035,.2,0,TAU);c.fill();
  c.strokeStyle='rgba(30,12,4,.7)';c.lineWidth=Math.max(1,sz*.025);body();c.stroke();
  // when it germinates, the coat splits along the ridge from the pointed end
  if(crack>0){const p=poly([[tx*.98,0],[tx*.55,w*.06],[tx*.1,w*.12],[-L*.2,w*.12],[-L*.42,w*.05]]);
    c.lineCap='round';c.strokeStyle='rgba(28,10,2,.92)';c.lineWidth=Math.max(1,sz*.08);strokePart(c,p,0,crack);
    c.globalCompositeOperation='lighter';c.strokeStyle=`rgba(255,190,110,${.4*crack})`;c.lineWidth=Math.max(1,sz*.03);strokePart(c,p,0,crack)}
  c.restore();
}
function soil(c,sz,vis,amb=0){
  c.fillStyle=`rgba(13,10,8,${vis})`;c.fillRect(-3*S,sz*.42,6*S,3*S);
  for(const g of G.grains){const lit=Math.exp(-Math.hypot(g.x,g.y)/(sz*3.2)),b=Math.min(1,lit+amb);
    c.fillStyle=`rgba(${20+150*lit+50*amb|0},${15+85*lit+44*amb|0},${11+40*lit+34*amb|0},${vis*(.22+.78*b)})`;
    c.beginPath();c.arc(g.x,g.y+sz*.42,g.r,0,TAU);c.fill()}
  c.strokeStyle=`rgba(96,70,48,${vis*.45})`;c.lineWidth=1.2*G.u;c.lineCap='round';for(const p of G.fine)strokePart(c,p,0,1);
}
function seedling(c,x,y,sz,o){
  if(o.root>0){c.save();c.translate(x,y);c.lineCap='round';c.strokeStyle='rgba(226,214,188,.85)';c.lineWidth=sz*.11;strokePart(c,G.rootP,0,o.root);
    c.lineWidth=Math.max(1,sz*.03);for(const h of G.hairs)if(h.f<o.root-.05){const q=at(G.rootP,h.f);c.beginPath();c.moveTo(q[0],q[1]);c.lineTo(q[0]+h.dx*sz,q[1]+h.dy*sz);c.stroke()}c.restore()}
  seed(c,x,y,sz,o.glow,o.crack);
  if(o.shoot>1){const bx=x+sz*.12,by=y-sz*.42,h=o.shoot,tx=bx-sz*.15,ty=by-h;
    c.lineCap='round';c.strokeStyle='#123222';c.lineWidth=sz*.17;c.beginPath();c.moveTo(bx,by);c.quadraticCurveTo(bx+sz*.45,by-h*.5,tx,ty);c.stroke();
    const L=sz*(.38+1.1*o.leaf);leaf(c,tx,ty,L,-Math.PI/2-.14-o.leaf*1.1,L*.34,'#14382a');leaf(c,tx,ty,L,-Math.PI/2+.14+o.leaf*1.1,L*.34,'#184232');
    c.save();c.globalCompositeOperation='lighter';c.strokeStyle='rgba(120,230,170,.28)';c.lineWidth=Math.max(1,sz*.03);c.beginPath();c.moveTo(bx-sz*.06,by);c.quadraticCurveTo(bx+sz*.39,by-h*.5,tx-sz*.06,ty);c.stroke();
    leaf(c,tx,ty,L*.96,-Math.PI/2-.14-o.leaf*1.1,L*.3,'rgba(110,220,160,.16)');leaf(c,tx,ty,L*.96,-Math.PI/2+.14+o.leaf*1.1,L*.3,'rgba(110,220,160,.16)');glow(c,tx,ty,L*1.2,'120,230,170',.12*o.leaf);c.restore()}
}
function dawnSky(c,gY,k,time){
  const g=c.createLinearGradient(0,0,0,gY);g.addColorStop(0,'#1d2c33');g.addColorStop(.55,'#6c786a');g.addColorStop(1,'#d8b67c');c.fillStyle=g;c.fillRect(0,0,W,gY+2);
  c.save();c.globalCompositeOperation='lighter';glow(c,W*.7,gY-H*.05,S*.75,GOLD,.32*k);c.restore();
  for(const t of G.trunks){c.fillStyle=`rgba(30,38,36,${t.a*.55})`;c.fillRect(t.x,0,t.w,gY)}
  mist(c,gY,.16*k,time,'215,212,196');
}
function mist(c,y,a,time,rgb){c.save();c.globalCompositeOperation='lighter';for(const m of G.mist){const x=((m.x+time*m.sp*18)%(W*1.6))-W*.3,yy=y+(m.y-.5)*H*.12;c.save();c.translate(x,yy);c.scale(1,.2);glow(c,0,0,m.w,rgb,a);c.restore()}c.restore()}
function grass(c,t,time,full){c.lineCap='round';for(const b of G.blades){const g=full?1:.15+.85*smooth(b.d,b.d+.45,t),h=b.h*g,sw=Math.sin(time*.8+b.ph)*h*.03*WIND,k=b.k;
  c.strokeStyle=k>.82?`rgba(214,196,120,.85)`:`rgb(${30+42*k|0},${50+52*k|0},${30+22*k|0})`;c.lineWidth=(1+1.6*k)*G.u*1.4;
  c.beginPath();c.moveTo(b.x,b.y);c.quadraticCurveTo(b.x+b.bend*h*.3,b.y-h*.6,b.x+b.bend*h*.6+sw,b.y-h);c.stroke()}}
function shafts(c,a,time){c.save();c.globalCompositeOperation='lighter';for(let i=0;i<4;i++){const x=W*(.48+i*.14),w=W*(.04+.03*(i%2)),br=a*(.65+.35*Math.sin(time*.4+i*1.7)),g=c.createLinearGradient(x,0,x-W*.3,H);g.addColorStop(0,`rgba(${GOLD},${.11*br})`);g.addColorStop(1,`rgba(${GOLD},0)`);c.fillStyle=g;c.beginPath();c.moveTo(x,0);c.lineTo(x+w,0);c.lineTo(x+w-W*.32,H);c.lineTo(x-W*.32,H);c.closePath();c.fill()}c.restore()}
function flies(c,a,time,rgb=GOLD){c.save();c.globalCompositeOperation='lighter';for(const f of G.flies){let x=f.x+Math.sin(time*f.sp+f.ph)*f.amp*2,y=f.y+Math.cos(time*f.sp*.7+f.ph)*f.amp;const tw=.5+.5*Math.sin(time*2*f.sp+f.ph*3);if(P.a>.01)[x,y]=lean(c,x,y);glow(c,x,y,7*G.u*(1+tw),rgb,a*(.3+.5*tw))}c.restore()}
function fern(c,f,u){const n=28;let x=f.x,y=f.y,a=-Math.PI/2+f.dir*.3;const curl=lerp(6,.7,u)*f.dir,step=f.L/n*(.45+.55*u),pts=[[x,y,a]];
  for(let i=1;i<=n;i++){const s=i/n;a+=curl*3*s*s/n;x+=Math.cos(a)*step;y+=Math.sin(a)*step;pts.push([x,y,a])}
  c.lineCap='round';c.strokeStyle='#0c1a14';c.lineWidth=2.6*G.u;c.beginPath();c.moveTo(pts[0][0],pts[0][1]);for(const p of pts)c.lineTo(p[0],p[1]);c.stroke();
  const lu=smooth(.25,.95,u);if(lu>0){c.strokeStyle='#10221a';c.lineWidth=2*G.u;for(let i=3;i<n-2;i+=2){const p=pts[i],l=f.L*.13*(1-i/n)*lu;for(const sd of[-1,1]){const aa=p[2]+sd*(Math.PI/2-.45);c.beginPath();c.moveTo(p[0],p[1]);c.lineTo(p[0]+Math.cos(aa)*l,p[1]+Math.sin(aa)*l);c.stroke()}}}}
const FLOWER=[['226,32,64','255,214,90'],['255,188,30','120,60,10'],['228,62,152','255,226,120'],['142,84,226','255,220,90'],['255,122,40','110,36,8'],['84,150,255','255,238,150'],['255,112,136','255,214,90']];
function flower(c,f,o,time){const[pc,cc]=FLOWER[f.i%FLOWER.length],dk=pc.split(',').map(v=>v*.45|0).join(',');const sw=Math.sin(time*.6+f.x)*3*G.u*WIND;
  c.strokeStyle='#0c1a14';c.lineWidth=2.4*G.u;c.beginPath();c.moveTo(f.x,H*1.02);c.quadraticCurveTo(f.x-f.r*.6,(f.y+H)/2,f.x+sw,f.y);c.stroke();
  c.save();c.translate(f.x+sw,f.y);
  if(o>0){c.globalCompositeOperation='lighter';glow(c,0,0,f.r*2.4*o,pc,.4*o);c.globalCompositeOperation='source-over'}
  const n=6;for(let i=0;i<n;i++){const ang=-Math.PI/2+(i-(n-1)/2)*lerp(.17,TAU/n,o),len=f.r*(.55+.45*o);c.save();c.rotate(ang);c.beginPath();c.ellipse(len*.5,0,len*.5,len*.22*(.6+.6*o),0,0,TAU);const pg=c.createLinearGradient(0,0,len,0);pg.addColorStop(0,`rgba(${dk},${.75+.2*o})`);pg.addColorStop(.55,`rgba(${pc},${.8+.2*o})`);pg.addColorStop(1,`rgba(${pc},${.9})`);c.fillStyle=pg;c.fill();c.strokeStyle=`rgba(255,255,255,${.12+.1*o})`;c.lineWidth=G.u;c.stroke();c.globalCompositeOperation='lighter';c.fillStyle=`rgba(${pc},${.22*o})`;c.fill();c.restore()}
  dot(c,0,0,f.r*.18,`rgba(${cc},${.5+.5*o})`);c.restore()}
function under(c,ox){const g=c.createLinearGradient(0,0,0,H);g.addColorStop(0,'#0d0a08');g.addColorStop(1,'#04070a');c.fillStyle=g;c.fillRect(0,0,W,H);
  for(const pass of[0,1]){c.fillStyle=pass?'rgba(70,56,44,.35)':'rgba(40,34,30,.5)';c.beginPath();for(const g of G.ug){if(g.k!==!!pass)continue;const x=((g.x+ox)%W+W)%W;c.moveTo(x+g.r,g.y);c.arc(x,g.y,g.r,0,TAU)}c.fill()}}
function bark(c,list,col='#33261c'){c.lineCap='round';c.strokeStyle=col;for(const p of list){c.lineWidth=p.w;strokePart(c,p,0,1)}}
function nightSky(c,hor,time){const g=c.createLinearGradient(0,0,0,hor);g.addColorStop(0,'#05080e');g.addColorStop(1,'#13202a');c.fillStyle=g;c.fillRect(0,0,W,H);
  for(const s of G.stars)dot(c,s.x,s.y,G.u*1.1,`rgba(220,230,240,${s.a*(.7+.3*Math.sin(time*.8+s.ph))})`);
  c.save();c.globalCompositeOperation='lighter';glow(c,W*.8,H*.17,S*.32,'170,200,220',.22);c.restore();dot(c,W*.8,H*.17,S*.028,'rgba(226,234,236,.92)')}

/* ---------- night garden style kit ----------
   Every shot shares one look: night sky and mist, near-black silhouettes with a thin moonlit rim,
   leafy shapes from the same foliage sprites, and light (glowing lines, pulses, fireflies) carrying the story. */
const RIM='170,205,225',NGFLY=['255,214,120','190,255,150','255,196,92','186,140,255','255,140,200'];
function buildNG(u){buildMagic();const r=rng(91);
  if(!MF.moon){MF.moon=MF.leaf[0].map(sp=>{const s=document.createElement('canvas');s.width=s.height=sp.width;const x=s.getContext('2d');x.filter=FILTER?'brightness(1.55) saturate(.85) hue-rotate(12deg)':'none';x.drawImage(sp,0,0);return s})}
  if(!MF.sil){MF.sil=['#0b1620','#08111a','#05090d'].map(col=>MF.leaf[0].map(sp=>{const s=document.createElement('canvas');s.width=s.height=sp.width;const x=s.getContext('2d');x.drawImage(sp,0,0);x.globalCompositeOperation='source-in';x.fillStyle=col;x.fillRect(0,0,s.width,s.height);return s}))}
  // horizon tree lines at three depths, drawn from the foliage sprites
  G.ngTrees=[0,1,2].map(l=>{const o=[],n=[34,22,12][l];for(let i=0;i<n;i++)o.push({x:(-.08+1.16*(i+r()*.8)/n)*W,s:S*[.11,.17,.26][l]*(.7+.6*r()),h:S*[.03,.06,.1][l]*(.5+r()),v:r()*4|0,tw:(.6+.8*r())*u*[2,3.5,6][l]});return o});
  G.ngFlies=[];for(let i=0;i<90;i++)G.ngFlies.push({x:r()*W,y:H*(.2+.75*r()),ph:r()*TAU,sp:.25+.6*r(),amp:(14+40*r())*u,col:NGFLY[(r()*NGFLY.length)|0],z:.5+r()});
  // light moving on water: short streaks that drift along the flow
  G.streaks=[];for(let i=0;i<46;i++)G.streaks.push({y:r()*2-1,off:r(),len:.02+.06*r(),sp:.06+.1*r(),a:.25+.6*r()});
  // forest floor seen from above (shots 13-17): leafy clumps scattered around the edges of the action
  G.floor=[];for(let i=0;i<900&&G.floor.length<70;i++){const x=(-.08+1.16*r())*W,y=(-.08+1.16*r())*H,s=S*(.07+.09*r());
    if(G.floor.some(q=>Math.hypot(q.x-x,q.y-y)<(q.s+s)*.42))continue;G.floor.push({x,y,s,v:r()*4|0,rot:r()*TAU})}
}
function ngSky(c,hor,time,moon=1){const g=c.createLinearGradient(0,0,0,Math.max(hor,H*.3));g.addColorStop(0,'#02050a');g.addColorStop(.7,'#08131d');g.addColorStop(1,'#10202b');c.fillStyle=g;c.fillRect(0,0,W,H);
  for(const s of G.stars)if(s.y<hor-8)dot(c,s.x,s.y,G.u*1.05,`rgba(220,230,245,${s.a*(.7+.3*Math.sin(time*.8+s.ph))})`);
  if(moon){c.save();c.globalCompositeOperation='lighter';glow(c,W*.78,H*.17,S*.42,'150,185,220',.2);c.restore();dot(c,W*.78,H*.17,S*.026,'rgba(232,240,250,.95)')}}
function ngTrees(c,hor,time,ox=0,layers=[0,1,2]){for(const l of layers){const sp=MF.sil[l],par=[.3,.6,1][l];
    c.fillStyle=['#0b1620','#08111a','#05090d'][l];c.globalAlpha=[.7,.85,1][l];
    for(const q of G.ngTrees[l]){const x=q.x+ox*par;c.fillRect(x-q.tw/2,hor-q.h-q.s*.2,q.tw,q.h+q.s*.2+2);c.drawImage(sp[q.v],x-q.s,hor-q.h-q.s*1.6,q.s*2,q.s*2)}c.globalAlpha=1;
    if(l<2)mist(c,hor-S*.02,.05,time*(.6+l*.2),'90,130,165')}}
function ngGround(c,gY){const g=c.createLinearGradient(0,gY,0,H);g.addColorStop(0,'#081014');g.addColorStop(1,'#020405');c.fillStyle=g;c.fillRect(0,gY,W,H-gY+2);
  c.strokeStyle=`rgba(${RIM},.12)`;c.lineWidth=G.u;c.beginPath();c.moveTo(0,gY+.5);c.lineTo(W,gY+.5);c.stroke()}
function ngGrass(c,t,time,full){c.lineCap='round';for(const b of G.blades){const g=full?1:.15+.85*smooth(b.d,b.d+.45,t),h=b.h*g,sw=Math.sin(time*.8+b.ph)*h*.03*WIND,tx=b.x+b.bend*h*.6+sw,ty=b.y-h;
    c.strokeStyle=`rgb(${6+8*b.k|0},${12+12*b.k|0},${11+9*b.k|0})`;c.lineWidth=(1+1.6*b.k)*G.u*1.4;c.beginPath();c.moveTo(b.x,b.y);c.quadraticCurveTo(b.x+b.bend*h*.3,b.y-h*.6,tx,ty);c.stroke();
    if(b.k>.7){c.strokeStyle=`rgba(${RIM},${.12+.2*(b.k-.7)})`;c.lineWidth=G.u*.9;c.beginPath();c.moveTo(b.x+b.bend*h*.3,b.y-h*.6);c.quadraticCurveTo(b.x+b.bend*h*.45,b.y-h*.8,tx,ty);c.stroke()}}}
function ngFlies(c,a,time,n=90){if(a<=0)return;c.save();c.globalCompositeOperation='lighter';for(let i=0;i<n&&i<G.ngFlies.length;i++){const f=G.ngFlies[i];
    let x=f.x+Math.sin(time*f.sp+f.ph)*f.amp*2,y=f.y+Math.cos(time*f.sp*.7+f.ph)*f.amp;const bl=Math.pow(.5+.5*Math.sin(time*f.sp*3+f.ph*3),2);if(P.a>.01)[x,y]=lean(c,x,y);
    glow(c,x,y,(5+9*bl)*f.z*G.u,f.col,a*(.25+.6*bl));if(bl>.5)dot(c,x,y,f.z*G.u,`rgba(255,250,230,${a*bl})`)}c.restore()}
// light drifting along water: short bright streaks moving downstream along a path (or a straight band)
function ngWater(c,p,width,time,a){c.save();c.globalCompositeOperation='lighter';c.lineCap='round';
  for(const s of G.streaks){const f=(time*s.sp+s.off)%1;c.strokeStyle=`rgba(${CYAN},${a*s.a*Math.sin(Math.PI*f)})`;c.lineWidth=G.u*(1+1.5*s.a);
    c.save();c.translate(0,s.y*width*.5);strokePart(c,p,f,Math.min(1,f+s.len));c.restore()}c.restore()}
// forest floor from above: dark ground, faint threads, leafy clumps with a moonlit edge
function ngFloor(c,ox=0,oy=0){c.fillStyle='#04090a';c.fillRect(0,0,W,H);
  c.strokeStyle='rgba(255,170,80,.05)';c.lineWidth=G.u;c.beginPath();for(const m of G.myc15){c.moveTo(m[0],m[1]);c.quadraticCurveTo(m[4],m[5],m[2],m[3])}c.stroke();
  for(const q of G.floor){const x=q.x+ox,y=q.y+oy;c.save();c.translate(x,y);c.rotate(q.rot);c.drawImage(MF.leaf[0][q.v],-q.s,-q.s,q.s*2,q.s*2);c.restore()}}

function youngTree(c,x,gY,g){c.save();c.translate(x,gY);
  c.save();c.globalCompositeOperation='lighter';glow(c,0,0,S*.28,AMBER,.16+.08*g);c.restore();
  c.lineCap='round';for(const b of G.tree){const f=clamp(g*7.4-b.l);if(f<=0)continue;const x2=lerp(b.x1,b.x2,f),y2=lerp(b.y1,b.y2,f),w=Math.max(1,b.w*(.35+.65*g));
    c.strokeStyle='#070d0c';c.lineWidth=w;c.beginPath();c.moveTo(b.x1,b.y1);c.lineTo(x2,y2);c.stroke();
    if(w>2.5){c.strokeStyle=`rgba(${RIM},.16)`;c.lineWidth=Math.max(1,w*.16);c.beginPath();c.moveTo(b.x1-w*.32,b.y1);c.lineTo(x2-w*.32,y2);c.stroke()}}
  const lg=smooth(.6,1,g);if(lg>0)for(const l of G.leaves){const s=l.r*3.4*lg;c.drawImage(MF.leaf[l.k<.55?0:1][(l.k*40|0)%4],l.x-s,l.y-s,2*s,2*s)}
  c.restore()}

/* ---------- the 23 shots ---------- */
const SC=[
// 01 opening seed: near-black, ember point, dolly in
(c,t,time)=>{c.fillStyle='#020304';c.fillRect(0,0,W,H);const z=lerp(.09,1,ease(t)),sx=W/2,sy=H*.6,sz=G.sz,vis=smooth(.14,.7,t);
  c.save();c.translate(sx,sy);c.scale(z,z);soil(c,sz,vis);c.restore();
  seed(c,sx,sy,sz*z,.4+.25*smooth(0,.5,t)+(.05+.1*IDLE)*Math.sin(time*1.4),0)},
// 02 seed cracks: root down, shoot up, glow stays dim
(c,t)=>{c.fillStyle='#020304';c.fillRect(0,0,W,H);const sx=W/2,sy=H*.6,sz=G.sz;c.save();c.translate(sx,sy);soil(c,sz,1);c.restore();
  seedling(c,sx,sy,sz,{crack:smooth(.05,.3,t),root:smooth(.2,.8,t),shoot:smooth(.38,1,t)*S*.17,leaf:0,glow:.65})},
// 03 the shoot rises into the night: the camera cranes up as it grows
(c,t,time)=>{const d=smooth(.1,.9,t),e=ease(t),sz=G.sz,sx=W/2,sy=H*.6+e*H*.3,hor=sy+sz*.42;
  c.fillStyle='#020304';c.fillRect(0,0,W,H);c.save();c.globalAlpha=d;ngSky(c,hor,time);ngTrees(c,hor,time,0,[0,1]);c.restore();
  c.save();c.translate(sx,sy);soil(c,sz,1,0);c.restore();
  seedling(c,sx,sy,sz,{crack:1,root:1,shoot:S*.17+e*S*.24,leaf:smooth(.45,.95,t),glow:.65});
  mist(c,hor-sz*.2,.1*d,time,'90,130,165');ngFlies(c,.45*d,time,24)},
// 04 the meadow grows under the moon, fireflies multiply
(c,t,time)=>{const gY=H*.68,ox=-ease(t)*W*.12;ngSky(c,gY,time);ngTrees(c,gY,time,ox*.5);ngGround(c,gY);
  c.save();c.translate(ox,0);for(const f of G.ferns)fern(c,f,smooth(f.d,f.d+.5,t));ngGrass(c,t,time,false);c.restore();
  ngFlies(c,.2+.7*smooth(.1,.6,t),time,30+(60*t|0))},
// 05 luminous flowers open one by one
(c,t,time)=>{const gY=H*.6;ngSky(c,gY,time);ngTrees(c,gY,time);ngGround(c,gY);const z=1+.16*ease(t);c.save();c.translate(W/2,H*.55);c.scale(z,z);c.translate(-W/2,-H*.55);
  ngGrass(c,1,time,true);for(const f of G.flowers)flower(c,f,smooth(f.d,f.d+.3,t),time);c.restore();mist(c,gY,.06,time,'90,130,165');ngFlies(c,.55,time,50)},
// 06 the young tree grows, the seed's warm light still at its base
(c,t,time)=>{const gY=H*.82;ngSky(c,gY,time);ngTrees(c,gY,time,0,[0,1]);ngGround(c,gY);
  const ox=Math.sin(ease(t)*1.3)*W*.03;youngTree(c,W/2+ox,gY,ease(t));
  c.save();c.translate(-ox*1.5,H*.08);ngGrass(c,1,time,true);c.restore();ngFlies(c,.4,time,45)},
// 07 the camera cranes down past the grown tree, through the forest floor into the dark soil
// (starts exactly where shot 06 ends, so the tree stays in frame as the ground rises past)
(c,t,time)=>{const e=ease(t),o=e*H*1.3,gY=H*.82-o,ox=Math.sin(1.3)*W*.03;c.fillStyle='#05070a';c.fillRect(0,0,W,H);
  if(gY>0){c.save();c.beginPath();c.rect(0,0,W,gY);c.clip();ngSky(c,gY,time);ngTrees(c,gY,time,0,[0,1]);c.restore()}
  const g=c.createLinearGradient(0,gY,0,gY+H*1.3);g.addColorStop(0,'#081014');g.addColorStop(.12,'#0d0b09');g.addColorStop(.4,'#090807');g.addColorStop(1,'#05080a');c.fillStyle=g;c.fillRect(0,Math.max(0,gY),W,H);
  c.save();c.translate(0,gY);const sv=smooth(.04,.3,t);
  c.globalAlpha=sv;for(const s of G.stones){c.fillStyle='#110f0d';c.beginPath();c.ellipse(s.x,s.y,s.rx,s.ry,s.a,0,TAU);c.fill();c.strokeStyle=`rgba(${RIM},.1)`;c.lineWidth=1.2*G.u;c.beginPath();c.ellipse(s.x,s.y,s.rx*.9,s.ry*.8,s.a,3.5,5.6);c.stroke()}
  c.translate(ox,0);c.lineCap='round';for(const p of G.bigRoots){c.strokeStyle='#1e1711';c.lineWidth=p.w;strokePart(c,p,0,.45);c.lineWidth=p.w*.65;strokePart(c,p,.4,.75);c.lineWidth=p.w*.35;strokePart(c,p,.7,1)}
  c.globalAlpha=1;c.restore();
  if(gY>-H*.9)youngTree(c,W/2+ox,gY,1);
  c.save();c.translate(-ox*1.5,H*.08-o);ngGrass(c,1,time,true);c.restore();ngFlies(c,.4*(1-e),time,45);
  c.save();c.globalCompositeOperation='lighter';glow(c,W/2,H*.9,S*.9,CYAN,.1*smooth(.45,1,t));c.restore()},
// 08 roots light up one by one
(c,t,time)=>{under(c,0);bark(c,G.net8);const N=G.net8.length;c.save();c.globalCompositeOperation='lighter';
  for(const p of G.net8){const a=p.rank/N*.82,la=smooth(a,a+.16,t);if(la<=0)continue;c.strokeStyle=`rgba(${CYAN},.3)`;c.lineWidth=Math.max(1,p.w*.35);strokePart(c,p,0,la);
    if(la<1){const q=at(p,la);glow(c,q[0],q[1],p.w*3+8*G.u,CYAN,.55)}else for(let k=0;k<2;k++)pulse(c,p,(time*70*G.u/p.len+p.off+k*.5)%1,CYAN,Math.max(2.2,p.w*.45),.8)}
  glow(c,W/2,H*.55,S,CYAN,.07*t);c.restore()},
// 09 the underground network, lateral dolly
(c,t,time)=>{const ox=-ease(t)*W*.6;under(c,ox*.5);c.save();c.translate(ox,0);
  c.save();c.globalCompositeOperation='lighter';for(const s of G.seeps){const g=c.createLinearGradient(0,s.y,0,s.y+s.len);g.addColorStop(0,'rgba(80,140,170,0)');g.addColorStop(.5,'rgba(80,140,170,.07)');g.addColorStop(1,'rgba(80,140,170,0)');c.fillStyle=g;c.fillRect(s.x,s.y,2.5*G.u,s.len);
    dot(c,s.x+G.u,s.y+((time*.15+s.ph)%1)*s.len,1.6*G.u,'rgba(140,200,220,.35)')}c.restore();
  bark(c,G.net9);c.save();c.globalCompositeOperation='lighter';
  c.strokeStyle=`rgba(${EMER},.16)`;c.lineWidth=.8*G.u;c.beginPath();for(const m of G.myc){c.moveTo(m.a[0],m.a[1]);c.quadraticCurveTo(m.m[0],m.m[1],m.b[0],m.b[1])}c.stroke();
  for(const p of G.net9){c.strokeStyle=`rgba(${CYAN},.2)`;c.lineWidth=Math.max(1,p.w*.3);strokePart(c,p,0,1)}
  G.net9.forEach((p,i)=>{if(i%2)return;pulse(c,p,(time*70*G.u/p.len+p.off)%1,i%4?CYAN:EMER,Math.max(2,p.w*.45),.85)});
  for(const m of G.myc){if(!m.lit)continue;const f=(time*.25+m.off)%1,u=1-f,x=u*u*m.a[0]+2*u*f*m.m[0]+f*f*m.b[0],y=u*u*m.a[1]+2*u*f*m.m[1]+f*f*m.b[1];glow(c,x,y,7*G.u,EMER,.5)}
  c.restore();c.restore()},
// 10 security: the infected section is sealed off and the light reroutes
(c,t,time)=>{under(c,0);const z=1+.05*ease(t);c.save();c.translate(W/2,H/2);c.scale(z,z);c.translate(-W/2,-H/2);
  c.save();c.globalCompositeOperation='lighter';c.strokeStyle=`rgba(${EMER},.07)`;c.lineWidth=.8*G.u;c.beginPath();for(const m of G.myc){c.moveTo(m.a[0],m.a[1]);c.quadraticCurveTo(m.m[0],m.m[1],m.b[0],m.b[1])}c.stroke();c.restore();
  const F=G.fungus,fg=smooth(0,.45,t),seal=smooth(.42,.6,t),dim=1-smooth(.35,.55,t),by=smooth(.52,.75,t),rr=smooth(.55,.78,t);
  const wM=S*.03,wL=S*.016;c.lineCap='round';
  c.strokeStyle='#33261c';for(const p of[G.top,G.bot]){c.lineWidth=wM;strokePart(c,p,0,1)}c.lineWidth=wL;for(const p of G.links)strokePart(c,p,0,1);
  c.lineWidth=wM;strokePart(c,G.segL,0,1);strokePart(c,G.segR,0,1);c.strokeStyle=`rgb(${lerp(51,24,1-dim)|0},${lerp(38,20,1-dim)|0},${lerp(28,22,1-dim)|0})`;strokePart(c,G.seg,0,1);
  c.strokeStyle='#33261c';c.lineWidth=wM*.8;strokePart(c,G.bypass,0,by);
  // fungus
  c.save();c.globalCompositeOperation='lighter';glow(c,F.x,F.y,S*.2*fg,'120,70,140',.18*fg);c.restore();
  const bg=c.createRadialGradient(F.x,F.y,0,F.x,F.y,S*.1*fg+1);bg.addColorStop(0,'rgba(10,4,12,.95)');bg.addColorStop(.75,'rgba(28,14,32,.9)');bg.addColorStop(1,'rgba(60,40,70,0)');c.fillStyle=bg;c.beginPath();c.arc(F.x,F.y,S*.1*fg+1,0,TAU);c.fill();
  c.strokeStyle='rgba(30,14,34,.95)';c.lineWidth=3*G.u;for(const d of F.tend){const pts=[];for(let k=0;k<=12;k++){const s=k/12*fg*.98,u=1-s;pts.push([u*u*F.x+2*u*s*d.cx+s*s*d.tx+Math.sin(s*9+time*.6)*d.ex*s,u*u*F.y+2*u*s*d.cy+s*s*d.ty])}c.beginPath();c.moveTo(pts[0][0],pts[0][1]);for(const q of pts)c.lineTo(q[0],q[1]);c.stroke()}
  // light
  c.save();c.globalCompositeOperation='lighter';c.strokeStyle=`rgba(${CYAN},.26)`;c.lineWidth=Math.max(1,wM*.3);
  for(const p of[G.top,G.bot,G.segL,G.segR])strokePart(c,p,0,1);c.lineWidth=Math.max(1,wL*.3);for(const p of G.links)strokePart(c,p,0,1);
  c.strokeStyle=`rgba(${CYAN},${.26*dim})`;c.lineWidth=Math.max(1,wM*.3);strokePart(c,G.seg,0,1);c.strokeStyle=`rgba(${CYAN},.3)`;strokePart(c,G.bypass,0,by);
  for(const x of[W*.47,W*.6]){const y=G.yAt(x);glow(c,x,y,S*.035*seal,AMBER,.5*seal)}
  const sp=110*G.u;for(let k=0;k<4;k++){pulse(c,G.top,(time*sp/G.top.len+k/4)%1,CYAN,3*G.u,.8);pulse(c,G.bot,(time*sp/G.bot.len+k/4+.12)%1,CYAN,3*G.u,.8);
    pulse(c,G.midFull,(time*sp/G.midFull.len+k/4+.3)%1,CYAN,3*G.u,.8*(1-rr)*(1-.85*(1-dim)));pulse(c,G.midB,(time*sp/G.midB.len+k/4+.3)%1,CYAN,3*G.u,.8*rr)}
  c.restore();
  if(seal>0){c.fillStyle='#2b1f17';for(const x of[W*.47,W*.6]){const y=G.yAt(x);c.beginPath();c.ellipse(x,y,wM*.55*seal,wM*.85*seal,0,0,TAU);c.fill()}}
  c.restore()},
// 11 follow one pulse down into underground water
(c,t,time)=>{const f=.02+ease(t)*.95,q=at(G.p11,f),camX=W*.42-q[0],camY=H*.5-q[1];under(c,camX*.4);c.save();c.translate(camX,camY);
  const ch=G.ch,wy=ch.y;c.fillStyle='#0f1113';c.beginPath();c.moveTo(ch.x-S*.4,wy+S*.6);c.lineTo(ch.x-S*.25,wy-S*.18);c.quadraticCurveTo(ch.x,wy-S*.3,ch.x+S*.6,wy-S*.22);c.lineTo(ch.x+S*5,wy-S*.22);c.lineTo(ch.x+S*5,wy+S*.6);c.closePath();c.fill();
  const wg=c.createLinearGradient(0,wy-S*.07,0,wy+S*.07);wg.addColorStop(0,'#071822');wg.addColorStop(.5,'#0b2a36');wg.addColorStop(1,'#061218');c.fillStyle=wg;c.fillRect(ch.x-S*.15,wy-S*.065,S*5,S*.13);
  const wet=smooth(G.p11water-.02,G.p11water+.05,f);
  ngWater(c,G.chP,S*.11,time,.3+.6*wet);
  c.lineCap='round';c.strokeStyle='#3a2b20';c.lineWidth=S*.03;strokePart(c,G.p11,0,G.p11water+.01);
  c.save();c.globalCompositeOperation='lighter';c.strokeStyle=`rgba(${CYAN},.18)`;c.lineWidth=S*.008;strokePart(c,G.p11,0,G.p11water);
  trail(c,G.p11,f,.06,CYAN,S*(.012+.02*wet),1);glow(c,q[0],q[1],S*(.06+.08*wet),CYAN,.6);dot(c,q[0],q[1],S*.008,'rgba(255,255,255,.9)');c.restore();c.restore()},
// 12 water emerges into a moonlit stream
(c,t,time)=>{const e=ease(t);c.save();c.translate(0,lerp(-H*.06,0,e));c.translate(W/2,H/2);c.scale(lerp(1.06,1,e),lerp(1.06,1,e));c.translate(-W/2,-H/2);
  ngSky(c,H*.5,time);ngTrees(c,H*.5,time);c.fillStyle='#060b0d';c.fillRect(-W*.1,H*.5,W*1.2,H*.6);mist(c,H*.53,.1,time,'90,130,165');
  const fl=smooth(0,.55,t);c.lineCap='round';
  for(let k=0;k<6;k++){c.strokeStyle='#0a1d26';const f0=k/6,f1=(k+1)/6;if(f0>fl)break;c.lineWidth=S*lerp(.02,.13,(f0+f1)/2);strokePart(c,G.stream,f0,Math.min(f1+.02,fl))}
  ngWater(c,G.stream,S*.05,time,fl);c.save();c.globalCompositeOperation='lighter';const m=at(G.stream,.02);glow(c,m[0],m[1],S*.12,CYAN,.25*fl);c.restore();
  const rg=c.createLinearGradient(0,H*.3,W*.32,H);rg.addColorStop(0,'#0c1013');rg.addColorStop(1,'#050708');c.fillStyle=rg;c.beginPath();G.rock.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();c.fill();
  c.strokeStyle=`rgba(${RIM},.2)`;c.lineWidth=1.4*G.u;c.beginPath();G.rock.slice(0,5).forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.stroke();
  c.strokeStyle='#020304';c.lineWidth=3*G.u;c.beginPath();c.moveTo(W*.255,H*.48);c.lineTo(W*.27,H*.55);c.lineTo(W*.262,H*.6);c.lineTo(W*.29,H*.66);c.stroke();
  for(const m of G.moss)dot(c,m.x,m.y,m.r,'rgba(34,74,58,.55)');c.restore();ngFlies(c,.35,time,30)},
// 13 separate glowing pools, none connected
(c,t,time)=>{forestTop(c,-ease(t)*W*.1,1,0,0,time)},
// 14 streams find each other and the light spreads
(c,t,time)=>{forestTop(c,-W*.1,lerp(1,.9,ease(t)),t,smooth(.35,1,t),time)},
// 15 automation: the long winding route
(c,t,time)=>{routes(c,0,1,((time*200*G.u/G.wind.len)+t*1.5)%1,-1,time)},
// 16 automation: a direct root replaces it
(c,t,time)=>{const g=smooth(.05,.45,t),wa=1-smooth(.45,.9,t);routes(c,g,wa,t<.45?((time*200*G.u/G.wind.len)+1.5)%1:-1,t>=.45?(time*200*G.u/G.direct.len)%1:-1,time)},
// 17 AI: chaos becomes routed flow
(c,t,time)=>{ngFloor(c);
  const on=smooth(.25,.85,t);c.lineCap='round';c.strokeStyle='#2c231b';c.lineWidth=S*.022;strokePart(c,G.trunk17,0,1);
  for(const p of G.paths17){c.lineWidth=S*.012;strokePart(c,p,0,1)}
  c.save();c.globalCompositeOperation='lighter';c.lineWidth=Math.max(1,S*.004);c.strokeStyle=`rgba(${EMER},${.12+.25*on})`;strokePart(c,G.trunk17,0,1);for(const p of G.paths17){c.strokeStyle=`rgba(${p.col},${.1+.28*on})`;strokePart(c,p,0,1)}
  glow(c,G.N0[0],G.N0[1],S*.06,EMER,.3+.3*on);for(const m of G.M)glow(c,m[0],m[1],S*.05,CYAN,.15+.45*on);
  const cx=W*.3,cy=H*.5,R=S*.36;
  for(const q of G.parts){const p=G.paths17[q.p],o=smooth(.15+.35*q.k,.45+.35*q.k,t);
    const hx=cx+Math.sin(time*q.ax+q.ph)*R*.9+Math.sin(time*1.7*q.ay+q.ph*2)*R*.3,hy=cy+Math.cos(time*q.ay+q.ph*1.3)*R*.75;
    let ox,oy;if(q.pause){const n=at(p,p.node);ox=n[0]+Math.sin(time+q.ph)*S*.012;oy=n[1]+Math.cos(time*1.3+q.ph)*S*.012}else{const n=at(p,(time*q.sp+q.off)%1);ox=n[0];oy=n[1]}
    let x=lerp(hx,ox,o),y=lerp(hy,oy,o);if(P.a>.01)[x,y]=lean(c,x,y);const col=o<.5?(q.warm?'250,190,130':'200,230,240'):p.col;
    dot(c,x,y,G.u*(1.6+1.2*q.k),`rgba(${col},.85)`);if(q.k>.7)glow(c,x,y,9*G.u,col,.35)}
  c.restore()},
// 18-21 the magic forest: enter at eye level, walk the path, look up and rise, turn over the canopy
(c,t,time)=>magic(c,t,time),
(c,t,time)=>magic(c,1+t,time),
(c,t,time)=>magic(c,2+t,time),
(c,t,time)=>magic(c,3+t,time),
// 22 the whole forest, breathing light
(c,t,time)=>{forest(c,G.zf*(1.05-.04*ease(t)),.17,true,1,time)},
// 23 the forest holds while the call to action comes up
(c,t,time)=>{forest(c,G.zf*(1.01-.02*ease(t)),.17,true,1,time)}
];

function forestTop(c,ox,z,st,bt,time){c.fillStyle='#071010';c.fillRect(0,0,W,H);c.save();c.translate(W/2,H/2);c.scale(z,z);c.translate(-W/2+ox,-H/2);
  const con=G.pools.map(()=>0);
  c.save();c.globalCompositeOperation='lighter';c.lineCap='round';
  G.streams.forEach(p=>{const s=smooth(.08+p.i*.07,.42+p.i*.07,st);if(s<=0)return;c.strokeStyle=`rgba(${CYAN},.1)`;c.lineWidth=S*.03;strokePart(c,p,0,s);c.strokeStyle=`rgba(${CYAN},.55)`;c.lineWidth=2*G.u;strokePart(c,p,0,s);if(s<1){const q=at(p,s);glow(c,q[0],q[1],S*.04,CYAN,.6)}else pulse(c,p,(time*.2+p.i*.17)%1,CYAN,3*G.u,.7)});
  G.streams.forEach(p=>{const s=smooth(.08+p.i*.07,.42+p.i*.07,st);const [a,b]=[[0,1],[1,2],[1,5],[2,3],[5,3],[3,4]][p.i];if(s>=1){con[a]++;con[b]++}});
  G.pools.forEach((p,i)=>{const a=.1+.22*Math.min(3,con[i]);glow(c,p.x,p.y,p.rx*1.9,CYAN,.22*a+.03*Math.sin(time+i))});c.restore();
  G.pools.forEach((p,i)=>{const g=c.createRadialGradient(p.x,p.y,0,p.x,p.y,p.rx);g.addColorStop(0,`rgba(${50+150*Math.min(1,con[i])},${45+105*Math.min(1,con[i])},${35+30*Math.min(1,con[i])},.5)`);g.addColorStop(1,'rgba(8,20,26,.62)');c.fillStyle=g;c.beginPath();c.ellipse(p.x,p.y,p.rx,p.ry,0,0,TAU);c.fill();dot(c,p.x+p.rx*.3,p.y-p.ry*.3,G.u*2,'rgba(220,235,240,.5)')});
  for(const q of G.canopies){const s=q.r*1.45;c.save();c.translate(q.x,q.y);c.rotate(q.ba);c.drawImage(MF.leaf[0][(q.ba*7|0)%4],-s,-s,2*s,2*s);c.restore()}
  c.save();c.globalCompositeOperation='lighter';for(const q of G.canopies){const b=smooth(q.d*.9+.05,q.d*.9+.3,bt);if(b>0){const x=q.x+Math.cos(q.ba)*q.r*1.05,y=q.y+Math.sin(q.ba)*q.r*1.05;glow(c,x,y,q.r*.6*b,'255,214,150',.55*b);dot(c,x,y,G.u*2.2*b,'rgba(255,230,190,.9)')}}c.restore();
  c.restore();mist(c,H*.5,.06,time,'170,195,210')}

function routes(c,dg,wa,fw,fd,time){ngFloor(c);
  c.lineCap='round';c.strokeStyle=`rgba(51,38,28,${wa})`;c.lineWidth=S*.012;strokePart(c,G.wind,0,1);if(dg>0){c.strokeStyle='#33261c';c.lineWidth=S*.016;strokePart(c,G.direct,0,dg)}
  c.save();c.globalCompositeOperation='lighter';c.strokeStyle=`rgba(${CYAN},${.16*wa})`;c.lineWidth=Math.max(1,S*.003);strokePart(c,G.wind,0,1);
  if(dg>0){c.strokeStyle=`rgba(${CYAN},.3)`;strokePart(c,G.direct,0,dg);if(dg<1){const q=at(G.direct,dg);glow(c,q[0],q[1],S*.04,CYAN,.5)}}
  if(fw>=0){trail(c,G.wind,fw,.05,CYAN,S*.01,wa);pulse(c,G.wind,fw,CYAN,S*.008,wa)}if(fd>=0){trail(c,G.direct,fd,.12,CYAN,S*.012,1);pulse(c,G.direct,fd,CYAN,S*.009,1)}c.restore();
  for(const P of[G.A,G.B]){c.save();c.globalCompositeOperation='lighter';glow(c,P[0],P[1],S*.22,AMBER,.16);c.restore();c.drawImage(MF.leaf[0][P===G.A?1:2],P[0]-S*.13,P[1]-S*.13,S*.26,S*.26)}}

function forest(c,z,netA,wave,riverA,time,A=1){c.globalAlpha=A;c.fillStyle='#03070a';c.fillRect(0,0,W,H);c.save();c.translate(W/2,H/2);
  // a slow breathing drift so the last shot never sits still
  const dz=z*(1+.014*Math.sin(time*.12));c.scale(dz,dz);c.rotate(Math.sin(time*.05)*.016);
  const vx=W/2/dz+70*G.u,vy=H/2/dz+70*G.u,Ls=G.Ls,B=G.bins,k=TAU/(700*G.u);
  for(let i=0,j=0;i<Ls.length;i+=8,j++){if(Math.abs(Ls[i]+Ls[i+2])/2>vx||Math.abs(Ls[i+1]+Ls[i+3])/2>vy){B[j]=9;continue}
    const w=wave?Math.pow(.5+.5*Math.sin(Ls[i+4]*k-time*1.1),6):0;B[j]=Math.min(4,(Ls[i+7]*(.7+1.6*w)*4.5)|0)}
  // the network beneath the canopy
  c.globalCompositeOperation='lighter';c.lineCap='round';c.lineWidth=1.7/dz;
  for(let b=0;b<5;b++){c.strokeStyle=`rgba(${CYAN},${Math.min(1,netA*(.35+b*1.25))})`;c.beginPath();for(let i=0,j=0;i<Ls.length;i+=8,j++)if(B[j]===b){c.moveTo(Ls[i],Ls[i+1]);c.quadraticCurveTo(Ls[i+5],Ls[i+6],Ls[i+2],Ls[i+3])}c.stroke()}
  if(riverA>0)for(const rv of G.rivers){c.strokeStyle=`rgba(${CYAN},${.06*riverA})`;c.lineWidth=30*G.u;strokePart(c,rv,0,1);c.strokeStyle=`rgba(${CYAN},${.32*riverA})`;c.lineWidth=2.2/dz;strokePart(c,rv,0,1);ngWater(c,rv,14*G.u,time*.6,.8*riverA)}
  // pulses travelling along the network
  for(let i=0,j=0;i<Ls.length;i+=8*7,j+=7){if(B[j]===9)continue;const f=(time*.35+j*.137)%1,u=1-f,x=u*u*Ls[i]+2*u*f*Ls[i+5]+f*f*Ls[i+2],y=u*u*Ls[i+1]+2*u*f*Ls[i+6]+f*f*Ls[i+3];gsprite(c,x,y,16*G.u,'255,196,92',.85*A*netA/.17)}
  c.globalAlpha=A;glow(c,0,0,90*G.u,AMBER,.32);
  // the canopy: dark leafy crowns with a faint moonlit texture, swaying slightly
  c.globalCompositeOperation='source-over';
  for(const q of G.crowns){if(Math.abs(q.x)>vx||Math.abs(q.y)>vy)continue;const sw=Math.sin(time*.5+q.ph)*q.r*.025*WIND;
    c.save();c.translate(q.x+sw,q.y);c.globalAlpha=A*.75;c.drawImage(MF.sil[2][q.v],-q.r*.9,-q.r*.85,q.r*2,q.r*2);c.rotate(q.rot);c.globalAlpha=A;c.drawImage(MF.moon[q.v],-q.r,-q.r,q.r*2,q.r*2);c.restore()}
  // the young tree at the centre, still carrying the seed's warm light
  c.globalAlpha=A;const yr=S*.1;c.save();c.rotate(.6);c.drawImage(MF.sil[2][2],-yr*.9,-yr*.85,yr*2,yr*2);c.drawImage(MF.moon[2],-yr,-yr,yr*2,yr*2);c.restore();
  c.globalAlpha=A;c.globalCompositeOperation='lighter';glow(c,0,0,yr*2.2,AMBER,.42+.08*Math.sin(time*1.3));glow(c,0,0,yr*.6,'255,214,150',.55);
  // the same network glows faintly through the leaves, so it reads as one connected web
  c.lineWidth=2/dz;for(let b=0;b<5;b++){c.strokeStyle=`rgba(${CYAN},${Math.min(1,netA*(.14+b*.5))})`;c.beginPath();for(let i=0,j=0;i<Ls.length;i+=8,j++)if(B[j]===b){c.moveTo(Ls[i],Ls[i+1]);c.quadraticCurveTo(Ls[i+5],Ls[i+6],Ls[i+2],Ls[i+3])}c.stroke()}
  // where a wave crest passes, light leaks up between the crowns
  for(let i=0,j=0;i<Ls.length;i+=8,j++)if(B[j]>=3)gsprite(c,(Ls[i]+Ls[i+2])/2,(Ls[i+1]+Ls[i+3])/2,30*G.u,'255,196,92',(B[j]-2)*.11*A);
  c.restore();c.globalAlpha=A;c.globalCompositeOperation='source-over';
  ngFlies(c,.65,time,70);mist(c,H*.45,.07,time,'110,150,185');mist(c,H*.8,.05,time*.7,'110,150,185');c.globalAlpha=1}

/* ---------- shots 18-21: the magic forest, one continuous 3D camera move (u runs 0..4 across the four shots) ---------- */
// world units are metres: y up, z forward along the path; the camera walks the path, looks up, rises through the canopy and turns to look down
const MF={ready:0},FOG=[17,32,46],MOON=(()=>{const v=[-.32,.82,.47],l=Math.hypot(...v);return v.map(a=>a/l)})();
const MCOL=['255,214,120','190,255,150','255,196,92','186,140,255','255,140,200','120,180,255'],MW=[.3,.18,.18,.14,.12,.08];
const mfPathX=z=>Math.sin(z*.045)*4+Math.sin(z*.017+1)*7;
